custom_css:
/* 美化名字：牛皮纸 · 莫兰迪手稿（稍深版·低饱和高级感） */
/* 二创作者：mukamuka */
/* 框架编写/整理：墨千尾（discord@这对吗/inkfoxxxx） */
/* 修复顶部导航栏图标全部相同的问题，恢复各自原本的图标 */

/* === 字体导入 === */
@import url("https://fonts.googleapis.com/css2?family=Great+Vibes&family=Dancing+Script:wght@400;700&display=swap");
@import url("https://fontsapi.zeoseven.com/438/main/result.css"); /* 汇文正楷 */
@import url("https://fontsapi.zeoseven.com/480/main/result.css"); /* 仓耳飞白字体 */

@font-face {
  font-family: "✏️";
  src: url("✏️");
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* === 全局变量（牛皮纸 · 莫兰迪低饱和 · 稍深版） === */
:root {
  --main-bg: #ede6db; /* 亚麻米白底加深 */
  --panel-bg: rgba(245, 238, 228, 0.94); /* 半透羊皮纸稍深 */
  --text-light: #3a3530; /* 深灰褐加深 */
  --text-dim: #5f574c; /* 暖灰褐加深 */
  --accent-green: #7f8e7d; /* 鼠尾草灰绿加深 */
  --accent-gold: #b39696; /* 干枯玫瑰灰粉加深 */
  --border-color: rgba(127, 142, 125, 0.4); /* 灰绿半透加强 */
  --gradient-green-gold: linear-gradient(135deg, #7f8e7d 0%, #b39696 100%);
  --gradient-dark: linear-gradient(
    180deg,
    #ddd0c0 0%,
    #cbbdaa 100%
  ); /* 牛皮纸渐变加深 */
  --ui-color-sec: rgba(245, 238, 228, 0.92); /* 米白基底加深 */
}

body {
  font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
  color: var(--text-light);
  background-color: var(--main-bg);
}

/* === 全局文字颜色（强制深色，但不透明） === */
body,
div,
p,
span,
a,
button,
input,
textarea,
select,
option,
label,
.drawer-content,
.options-content,
.mes_text,
.mes_text * {
  color: var(--text-light) !important;
}
.mes_timer,
.tokenCounterDisplay,
.mesIDDisplay,
.ch_name .timestamp {
  color: var(--text-dim) !important;
}

/* === 所有弹窗、抽屉、列表背景统一为浅色半透明 === */
.drawer-content,
.options-content,
#table_drawer_content,
.popup-content,
.ui-widget-content,
.select2-dropdown,
.select2-container--default .select2-results,
.jse-main,
[data-v-81d837f8].TH-custom-tailwind,
#select_chat_popup,
#select_chat_div,
.select_chat_block,
.select_chat_block_wrapper,
.chatBackupsList,
#dialogue_popup,
#character_popup,
#world_popup {
  background: var(--panel-bg) !important;
  backdrop-filter: blur(10px);
  border: 1px solid var(--border-color) !important;
}

.select_chat_block {
  background: rgba(245, 238, 228, 0.88) !important;
  margin-bottom: 8px;
  border-radius: 8px;
  padding: 8px;
}
.select_chat_block:hover {
  background: rgba(245, 238, 228, 0.98) !important;
}

/* === 顶栏（保留自定义渐变和图标效果，且保持各自原本的图标） === */
#top-settings-holder {
  background: var(--gradient-dark);
  border-bottom: 1px solid var(--accent-green);
  box-shadow: 0 2px 8px rgba(127, 142, 125, 0.25);
}
#top-bar {
  background: transparent !important;
}

#top-settings-holder .drawer-icon {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  width: auto !important;
  height: auto !important;
  font-size: 20px !important;
  line-height: 1;
}

/* 深色莫兰迪渐变 —— 足够明显 */
#top-settings-holder .drawer-icon::before {
  color: transparent !important;
  background: linear-gradient(135deg, #2e4030 0%, #6e4e4e 100%);
  -webkit-background-clip: text;
  background-clip: text;
  transition: all 0.3s ease;
}

#top-settings-holder .drawer-icon:hover::before {
  filter: drop-shadow(0 0 6px #b39696);
  transform: scale(1.1);
}

#top-settings-holder .drawer-icon.openIcon {
  background: transparent !important;
}
#top-settings-holder .drawer-icon.openIcon::before {
  color: transparent !important;
  background: linear-gradient(135deg, #1e2e1e 0%, #5a3a3a 100%);
  -webkit-background-clip: text;
  background-clip: text;
}

/* === 底栏（保留输入框样式，底栏图标也保持透明背景+渐变） === */
#send_form {
  background: var(--gradient-dark);
  border-top: 1px solid var(--accent-green) !important;
  border-radius: 15px 15px 0 0 !important;
  padding: 10px;
  box-shadow: 0 -2px 8px rgba(127, 142, 125, 0.25);
}
#send_textarea {
  background: rgba(255, 245, 235, 0.92) !important;
  border: 1px solid var(--border-color) !important;
  border-radius: 10px !important;
  color: var(--text-light) !important;
  padding: 8px !important;
}
#send_form [class*="fa-"] {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
#send_form [class*="fa-"]::before {
  font-size: 18px;
  color: transparent !important;
  background: var(--gradient-green-gold);
  -webkit-background-clip: text;
  background-clip: text;
  transition: all 0.2s ease;
}
#send_form [class*="fa-"]:hover::before {
  filter: drop-shadow(0 0 5px var(--accent-gold));
  transform: scale(1.1);
}

/* === 聊天区域（完美布局原封不动 · 仅配色替换为牛皮纸莫兰迪浅色） === */
#sheld {
  height: calc(
    var(--doc-height, 100vh) - var(--topBarBlockSize, 45px) - 1px
  ) !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

#chat {
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  overflow-y: scroll !important;
  overflow-x: hidden !important;
  max-height: calc(
    var(--doc-height, 100vh) - var(--topBarBlockSize, 45px) - 20px
  ) !important;
  padding-left: 6px !important;
  padding-right: 0px;
  display: flex;
  flex-direction: column;
  gap: 0px;
}

.mesAvatarWrapper {
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100% !important;
}

.mesAvatarWrapper .avatar {
  margin: 0 0 35px 0 !important;
  width: 100% !important;
  height: 320px !important;
  flex: 0 0 auto !important;
  position: relative;
  pointer-events: none !important;
}

.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
  object-position: 50% 20%;
  border-radius: 12px 12px 0 0 !important;
  border: none !important;
  image-rendering: -webkit-optimize-contrast;
  image-rendering: high-quality;

  -webkit-mask-image: linear-gradient(
    to bottom,
    black 60%,
    rgba(0, 0, 0, 0.8) 75%,
    rgba(0, 0, 0, 0.4) 88%,
    rgba(0, 0, 0, 0.1) 95%,
    transparent 100%
  );
  mask-image: linear-gradient(
    to bottom,
    black 60%,
    rgba(0, 0, 0, 0.8) 75%,
    rgba(0, 0, 0, 0.4) 88%,
    rgba(0, 0, 0, 0.1) 95%,
    transparent 100%
  );
}

.mesAvatarWrapper .avatar img {
  pointer-events: auto !important;
  -webkit-user-drag: none !important;
  user-select: none !important;
  -webkit-touch-callout: none !important;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: contents;
  color: var(--text-dim);
}

#chat .ch_name {
  position: static;
  align-items: flex-end;
  padding: calc(var(--mainFontSize) * 0.8) 0;
  font-size: 0.9em;
  color: var(--text-light);
}

#chat .ch_name::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background-color: var(--border-color);
}

.mes {
  width: 100%;
  flex-direction: column !important;
  align-items: center !important;
  border: none !important;
  margin: 0 0 0px 0 !important;
  padding: 0 !important;
  background-color: transparent !important;
  position: relative !important;
}

.mes .ch_name .name_text {
  position: absolute !important;
  top: 330px !important;
  left: 0 !important;
  right: 0 !important;
  margin: 0 auto !important;
  width: 100% !important;
  text-align: center !important;
  font-family: "TsangerFeiBai W03", "Great Vibes", cursive !important;
  font-size: 1.8em !important;
  font-weight: normal !important;
  color: var(--accent-gold) !important;
  z-index: 99 !important;
  pointer-events: none !important;
  display: block !important;
  opacity: 1 !important;
  visibility: visible !important;

  text-shadow:
    0 1px 3px rgba(250, 240, 230, 0.8),
    0 2px 6px rgba(127, 142, 125, 0.4),
    0 0 8px rgba(179, 150, 150, 0.4) !important;
}

.mes_text {
  padding: calc(var(--mainFontSize) * 0.8) 0 0 0;
}

.mes_text q,
.mes_text “q” {
  color: #9e6f68;
  font-style: italic;
}

.mes_text i,
.mes_text em {
  color: #6a7e6a;
}

.mes_block {
  width: 98%;
  padding-left: 0;
  padding-bottom: 15px;
}

.last_mes .mes_text {
  padding-right: 0;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

div[is_user="false"].last_mes .mes_block {
  padding-bottom: 50px;
}

/* === 牛皮纸莫兰迪气泡配色（仅替换颜色，不动任何尺寸） === */

div[is_user="true"].mes {
  background: linear-gradient(
    to bottom,
    rgba(245, 235, 222, 0.95),
    rgba(235, 222, 210, 0.92)
  ) !important;
  backdrop-filter: blur(12px);
  border: 1px solid rgba(179, 150, 150, 0.5) !important;
  border-top: 4px solid var(--accent-gold) !important;
  border-radius: 12px;
  margin-bottom: 20px !important;
  box-shadow: 0 4px 12px rgba(127, 142, 125, 0.15) !important;
}

div[is_user="true"] .avatar img {
  box-shadow: none !important;
  border: none !important;
}

div[is_user="false"].mes {
  background: linear-gradient(
    to bottom,
    rgba(238, 230, 220, 0.95),
    rgba(225, 215, 205, 0.92)
  ) !important;
  backdrop-filter: blur(12px);
  border: 1px solid rgba(143, 158, 141, 0.5) !important;
  border-top: 4px solid var(--accent-green) !important;
  border-radius: 12px;
  margin-bottom: 20px !important;
  box-shadow: 0 4px 12px rgba(127, 142, 125, 0.15) !important;
}

div[is_user="false"] .avatar img {
  box-shadow: none !important;
  border: none !important;
}

.last_mes .swipeRightBlock {
  margin: 0 10px 0 0;
}

.swipe_left {
  left: calc(8px + 5px);
}

.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
}

.swipes-counter {
  margin-bottom: 4px;
}

#chat .mes.selected {
  background-color: rgba(143, 158, 141, 0.25) !important;
}

body.documentstyle #chat .ch_name::after {
  width: 0;
}

body.documentstyle #chat .mes .mes_block {
  margin-right: 0;
  padding-bottom: 15px;
}

/* === 收藏栏横向滑动（修复头像双层框） === */
#HotSwapWrapper {
  overflow: hidden;
}
#HotSwapWrapper > div {
  overflow: auto hidden !important;
  display: flex !important;
  flex-wrap: nowrap !important;
  justify-content: flex-start !important;
  gap: 12px !important;
  min-height: 120px !important;
  padding: 10px 0 !important;
  scrollbar-width: thin;
}
#HotSwapWrapper > div .avatar {
  width: 90px !important;
  height: 90px !important;
  flex: 0 0 auto !important;
  border-radius: 12px !important;
  overflow: hidden !important;
  box-shadow: 0 2px 8px rgba(127, 142, 125, 0.3) !important;
  border: none !important;
  background: transparent !important;
  padding: 0 !important;
}
#HotSwapWrapper > div .avatar img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border: none !important;
  border-radius: inherit !important;
}

/* === 表格（牛皮纸莫兰迪风格 · 结构优化版） === */
.mes_text {
  position: relative;
  padding-bottom: 20px;
}

.mes_text table {
  display: block;
  width: auto;
  min-width: 100%;
  max-width: max-content;
  margin: 12px 0;
  border-collapse: separate;
  border-spacing: 0;
  border-radius: 12px;
  background: linear-gradient(
    145deg,
    rgba(245, 238, 225, 0.85) 0%,
    rgba(235, 226, 213, 0.98) 100%
  );
  background-clip: padding-box;
  border: 1px solid rgba(127, 142, 125, 0.4);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  overflow-x: auto;
  overflow-y: visible;
  padding-bottom: 6px;
}

.mes_text table > thead,
.mes_text table > tbody,
.mes_text table > tr {
  display: table;
  width: 100%;
  table-layout: auto;
}

.mes_text table > thead {
  display: table-header-group;
}

.mes_text table > tbody {
  display: table-row-group;
}

.mes_text table tr {
  display: table-row;
}

.mes_text table thead tr {
  background: linear-gradient(145deg, #a3b2a1 0%, var(--accent-gold) 100%);
}

.mes_text table th,
.mes_text table td {
  display: table-cell;
  padding: 12px 16px;
  text-align: left;
  vertical-align: top;
  white-space: nowrap;
  font-size: calc(var(--mainFontSize) * 0.9);
  line-height: 1.4;
  border: 1px solid rgba(127, 142, 125, 0.35);
}

.mes_text table th {
  background: transparent;
  color: #3a3530;
  font-weight: 600;
  text-align: center;
  border-bottom-width: 2px;
  border-color: rgba(127, 142, 125, 0.6);
}

.mes_text table td {
  color: var(--text-light);
}

.mes_text table tbody tr:hover {
  background: rgba(127, 142, 125, 0.18) !important;
}

.mes_text table tbody tr:nth-child(even) {
  background: rgba(160, 145, 130, 0.06);
}

.mes_text table tbody tr:nth-child(even):hover {
  background: rgba(127, 142, 125, 0.22) !important;
}

.mes_text table::-webkit-scrollbar {
  height: 4px;
}
.mes_text table::-webkit-scrollbar-track {
  background: rgba(235, 225, 215, 0.7);
  border-radius: 4px;
  margin: 0 12px;
  border: 0.5px solid rgba(127, 142, 125, 0.5);
  box-shadow: inset 0 0 3px rgba(0, 0, 0, 0.05);
}
.mes_text table::-webkit-scrollbar-thumb {
  background: var(--gradient-green-gold);
  border-radius: 4px;
  border: 1px solid rgba(179, 150, 150, 0.5);
  box-shadow: 0 0 4px rgba(127, 142, 125, 0.5);
  min-width: 50px;
  max-width: 70vw;
}
.mes_text table::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(
    90deg,
    #8f9e8d 0%,
    var(--accent-gold) 50%,
    #8f9e8d 100%
  );
  box-shadow: 0 0 6px rgba(179, 150, 150, 0.7);
}

/* ========= 普通按钮、输入框、下拉框（仅莫兰迪配色，形状完全自由） ========= */
.menu_button,
.interactable,
button,
input[type="button"],
input[type="submit"],
input[type="reset"],
.popup-button-ok,
.popup-button-cancel,
#dialogue_del_mes_ok,
#dialogue_del_mes_cancel,
.redWarningBG,
.red_button {
  background: rgba(245, 238, 228, 0.92) !important;   /* 浅羊皮纸色，半透明 */
  border: 1px solid rgba(127, 142, 125, 0.4) !important; /* 鼠尾草绿边框 */
  color: #3a3530 !important;                          /* 深灰褐文字 */
  box-shadow: none !important;
  transition: none !important;
  cursor: pointer;
}

/* 悬停效果：颜色稍深，更有互动感 */
.menu_button:hover,
.interactable:hover,
button:hover {
  background: rgba(255, 245, 235, 0.98) !important;
  border-color: #b39696 !important;                   /* 干枯玫瑰粉 */
  transform: none !important;
  box-shadow: none !important;
}

/* 红色警告按钮（删除等）保留红色调但融入莫兰迪 */
#delete_button,
#dialogue_del_mes_ok,
.redWarningBG,
.red_button {
  background: rgba(156, 106, 106, 0.88) !important;   /* 低饱和玫瑰棕 */
  border-color: #9c6a6a !important;
  color: white !important;
}
#delete_button:hover,
#dialogue_del_mes_ok:hover {
  background: #8f5f5f !important;
}

/* 输入框、文本框、下拉框：浅色底，不强制内边距/圆角 */
input,
textarea,
select,
.text_pole {
  background: rgba(255, 245, 235, 0.92) !important;   /* 暖白底 */
  border: 1px solid rgba(127, 142, 125, 0.4) !important;
  color: #3a3530 !important;
}

input:focus,
textarea:focus,
select:focus {
  background: #fff8f0 !important;
  border-color: #b39696 !important;
  outline: none;
}

/* 复选框定制：保持风格但尺寸由系统决定 */
input[type="checkbox"] {
  accent-color: #7f8e7d; /* 现代浏览器勾选颜色 */
}
input[type="checkbox"] {
  appearance: none;
  width: 18px;
  height: 18px;
  background: rgba(245, 238, 228, 0.92);
  border: 1.5px solid rgba(127, 142, 125, 0.55);
  border-radius: 4px;
  cursor: pointer;
}
input[type="checkbox"]:checked {
  background: linear-gradient(145deg, #7f8e7d, #b39696);
  border-color: transparent;
}
input[type="checkbox"]:checked::after {
  content: "✓";
  color: #fff8f0;
  font-size: 13px;
  display: block;
  text-align: center;
  line-height: 1;
}
::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}
::-webkit-scrollbar-track {
  background: rgba(215, 205, 193, 0.5);
  border-radius: 10px;
}
::-webkit-scrollbar-thumb {
  background: var(--gradient-green-gold);
  border-radius: 10px;
}

/* ========= 修复特定组件的黑色色块 ========= */
.jse-menu,
.jse-navigation-bar,
.jse-search-box-container,
.jse-contents {
  background: rgba(245, 238, 228, 0.96) !important;
  color: var(--text-light) !important;
}
.jse-button,
.jse-navigation-bar-button {
  background: var(--ui-color-sec) !important;
  border: 1px solid var(--border-color) !important;
  color: var(--text-light) !important;
  border-radius: 4px;
  padding: 4px 8px;
}
.jse-button:hover,
.jse-navigation-bar-button:hover {
  background: #fff8f0 !important;
  border-color: var(--accent-gold) !important;
}
.jse-separator {
  background: var(--border-color) !important;
}
.jse-key {
  color: #5f6e5d !important;
}
.jse-value.jse-string {
  color: #9e6f68 !important;
}
.jse-value.jse-number {
  color: #4f4a44 !important;
}
.jse-expand svg {
  fill: #4f4a44 !important;
}
.dataBankAttachments,
.dataBankAttachments .attachmentsList,
.dataBankAttachments .attachmentListItem {
  background: rgba(245, 238, 228, 0.96) !important;
  color: var(--text-light) !important;
}
.dataBankAttachments input,
.dataBankAttachments select,
.dataBankAttachments textarea {
  background: rgba(255, 245, 235, 0.98) !important;
  border: 1px solid var(--border-color) !important;
  color: var(--text-light) !important;
}
.dataBankAttachments .menu_button,
.dataBankAttachments .interactable,
.dataBankAttachments .right_menu_button {
  background: var(--ui-color-sec) !important;
  border: 1px solid var(--border-color) !important;
  border-radius: 6px !important;
  color: var(--text-light) !important;
  padding: 4px 10px !important;
  box-shadow: none;
}
.dataBankAttachments .menu_button:hover,
.dataBankAttachments .interactable:hover {
  background: #fff8f0 !important;
  border-color: var(--accent-gold) !important;
}
.dataBankAttachments .attachmentListItem .right_menu_button {
  background: transparent !important;
  border: none !important;
  padding: 2px !important;
}
.dataBankAttachments .attachmentListItem .right_menu_button i {
  color: var(--text-dim) !important;
}
.dataBankAttachments .attachmentListItem .right_menu_button:hover i {
  color: var(--accent-gold) !important;
}
.actionButtonsModal {
  background: rgba(245, 238, 228, 0.98) !important;
  border: 1px solid var(--border-color) !important;
  backdrop-filter: blur(8px);
}
.actionButtonsModal .list-group-item {
  background: transparent !important;
  color: var(--text-light) !important;
}
.actionButtonsModal .list-group-item:hover {
  background: rgba(127, 142, 125, 0.12) !important;
}
#Backgrounds.drawer-content,
#bg-header-fixed,
