/* ========= 修复复选框勾选标记（✓）不可见 ========= */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  background: rgba(245, 238, 228, 0.92);
  border: 1.5px solid rgba(127, 142, 125, 0.65);
  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
  vertical-align: middle;
  margin-right: 4px;
}
input[type="checkbox"]:checked {
  background: linear-gradient(145deg, #7f8e7d, #b39696);
  border-color: transparent;
}
input[type="checkbox"]:checked::after {
  content: "✓";
  display: block;
  color: #fff8f0;
  font-size: 13px;
  font-weight: bold;
  text-align: center;
  line-height: 1;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: auto;
  height: auto;
}
input[type="checkbox"]:checked::before {
  display: none;
}
input[type="checkbox"]:checked {
  background: linear-gradient(145deg, #7f8e7d, #993399) !important;
}
input[type="checkbox"]:checked::after {
  content: "✓" !important;
  color: #fff8f0 !important;
  font-size: 13px !important;
  display: block !important;
}

