/* ========= 全局滚动条美化（莫兰迪牛皮纸 · 可见版） ========= */
/* 覆盖所有可能出现滚动条的元素 */
::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}

::-webkit-scrollbar-track {
  background: rgba(235, 225, 215, 0.6); /* 浅灰褐轨道，清晰可见 */
  border-radius: 8px;
  margin-block: 2px; /* 上下留一点间距 */
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(145deg, #8f9e8d, #b39696); /* 主题渐变滑块 */
  border-radius: 8px;
  border: 1px solid rgba(255, 250, 240, 0.4);
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(145deg, #7a8a78, #a58383);
}

::-webkit-scrollbar-corner {
  background: rgba(235, 225, 215, 0.4);
}

/* 对于 Firefox 的滚动条支持 */
* {
  scrollbar-width: thin;
  scrollbar-color: #8f9e8d rgba(235, 225, 215, 0.5);
}

