#user-settings .standoutHeader,
#user-settings h4,
#extensions-panel .standoutHeader,
#extensions-panel h4,
#world_popup .standoutHeader,
#world_popup h4,
.popup-content .standoutHeader,
.popup-content h4[data-i18n] {
  /* 背景改为浅色半透明羊皮纸，同时移除可能存在的深色渐变 */
  background: rgba(245, 238, 228, 0.85) !important;
  background-image: none !important;

  /* 边框只改颜色，保留原有粗细和样式（如 solid、dashed 等） */
  border-color: rgba(127, 142, 125, 0.5) !important;

  /* 文字改为深灰褐 */
  color: #3a3530 !important;

  /* 清除可能附带的深色文字阴影或盒子阴影（不影响布局） */
  text-shadow: none !important;
  box-shadow: none !important;
}

/* 确保标题内的图标、小字也保持深色（可选） */
.drawer-content .standoutHeader *,
.drawer-content h4[data-i18n] * {
  color: #3a3530 !important;
}
/* === 终极修复：覆盖所有设置面板内的标题栏（包括嵌套 span 等情况）=== */
.drawer-content h4:has([data-i18n]),
.drawer-content h3:has([data-i18n]),
.drawer-content h4[data-i18n],
.drawer-content h3[data-i18n],
.drawer-content .standoutHeader,
#options h4:has([data-i18n]),
#options h3:has([data-i18n]),
#options .standoutHeader,
#user-settings h4:has([data-i18n]),
#user-settings h3:has([data-i18n]),
#user-settings .standoutHeader,
#extensions-panel h4:has([data-i18n]),
#extensions-panel .standoutHeader,
#world_popup h4:has([data-i18n]),
#world_popup .standoutHeader,
.popup-content h4:has([data-i18n]),
.popup-content .standoutHeader {
  /* 背景改为浅色半透明羊皮纸，移除深色渐变 */
  background: rgba(245, 238, 228, 0.85) !important;
  background-image: none !important;

  /* 边框只改颜色，保留原有粗细和样式 */
  border-color: rgba(127, 142, 125, 0.5) !important;

  /* 文字改为深灰褐 */
  color: #3a3530 !important;

  /* 清除深色阴影，不影响布局 */
  text-shadow: none !important;
  box-shadow: none !important;
}

/* 兼容不支持 :has() 的浏览器：直接命中包含 data-i18n 的 span 所在的 h4 */
.drawer-content h4 span[data-i18n],
.drawer-content h3 span[data-i18n] {
  /* 确保内部 span 的文字颜色也被继承 */
  color: inherit !important;
}

/* 确保标题内所有子元素（图标、小字）颜色正确 */
.drawer-content h4:has([data-i18n]) *,
.drawer-content h3:has([data-i18n]) *,
.drawer-content .standoutHeader * {
  color: #3a3530 !important;
}

.mes_text *:is(q, .quote, [class*="quote"], [data-quote]) {
  color: #9e6f68 !important;
  font-style: italic;
}
/* === 彻底消除 #options 黑边：重置 padding，背景色下放 === */
#options {
  padding: 0 !important;          /* 移除可能露出深色背景的内边距 */
  background-color: transparent !important; /* 父级透明，由子级负责背景 */
}

#options .options-content {
  padding: 2px !important;        /* 将原 padding 转移至此，保留间距 */
  background-color: var(--panel-bg, rgba(245, 238, 228, 0.94)) !important; /* 使用浅色主题背景 */
  border-radius: 10px !important; /* 保持圆角 */
  box-shadow: none !important;
}

/* 如果上述还不够，同时确保包裹层完全透明 */
body > div:has(> #options) {
  background-color: transparent !important;
  padding: 0 !important;
}
